const entrada = $input.first().json;
const esperado = $env.ADORBIT_N8N_WEBHOOK_TOKEN;
const recibido = (entrada.headers || {})['x-webhook-token'];
const fallo = (estado_http, codigo, mensaje) => [{ json: { ok: false, estado_http, respuesta: { codigo, mensaje } } }];
if (!esperado || recibido !== esperado) return fallo(401, 'no_autenticado', 'Falta o es invalido el encabezado X-Webhook-Token');
const b = entrada.body || {};

const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const errores = {};
if (!uuidRe.test(b.cliente_id || '')) errores.cliente_id = 'UUID invalido';
if (typeof b.nombre_campana !== 'string' || b.nombre_campana.trim() === '' || b.nombre_campana.length > 200) errores.nombre_campana = 'Obligatorio, maximo 200 caracteres';
if (!['BOB', 'USD'].includes(b.moneda)) errores.moneda = 'BOB o USD';
if (!Array.isArray(b.items) || b.items.length < 1 || b.items.length > 90) errores.items = 'Entre 1 y 90 items';
else b.items.forEach((it, i) => {
  if (!it || typeof it.descripcion !== 'string' || !it.descripcion.trim() || it.descripcion.length > 200) errores[`items[${i}].descripcion`] = 'Obligatoria';
  if (!Number.isInteger(it.cantidad) || it.cantidad < 1) errores[`items[${i}].cantidad`] = 'Entero >= 1';
  if (!/^\d{1,12}(\.\d{1,2})?$/.test(String(it.precio_unitario))) errores[`items[${i}].precio_unitario`] = 'Decimal como texto, ej. "1500.00"';
});
if (Object.keys(errores).length) return [{ json: { ok: false, estado_http: 400, respuesta: { codigo: 'solicitud_invalida', mensaje: 'Hay campos invalidos', detalle: errores } } }];
const huella = hash(JSON.stringify([b.cliente_id, b.nombre_campana, b.moneda, b.items]));
return [{ json: { ok: true, clave: 'pedido-' + huella, pedido: { cliente_id: b.cliente_id, nombre_campana: b.nombre_campana.trim(), moneda: b.moneda, items: b.items.map((i) => ({ descripcion: i.descripcion.trim(), cantidad: i.cantidad, precio_unitario: String(i.precio_unitario) })) } } }];

} catch (e) {
  return [{ json: { ok: false, estado_http: 500, respuesta: { codigo: 'error_interno', mensaje: 'Fallo interno del flujo', detalle: String((e && e.message) || e) } } }];
}

